1	// Package snapshot implements a persistent key-value store whose readers
2	// operate on immutable point-in-time snapshots. A snapshot never observes a
3	// write committed after it was acquired, and it keeps serving its fixed view
4	// even after the store that produced it has been closed.
5	package snapshot
6	
7	import (
8		"errors"
9		"io/fs"
10		"os"
11		"sync"
12		"sync/atomic"
13	)
14	
15	// viewFlattenLimit bounds how deep an overlay chain a published view grows
16	// before the next commit builds it on a flattened copy. Without a bound the
17	// chain would gain one map per commit for the life of the store and memory
18	// would track cumulative commits; flattening every viewFlattenLimit commits
19	// keeps live depth (and the work a read or checkpoint walk does) independent
20	// of commit count, while the flattened copies stay immutable for every
21	// snapshot already holding an older view.
22	const viewFlattenLimit = 64
23	
24	// node is one immutable version in a key's history. Versions form a linked
25	// list from newest to oldest; a snapshot pins the head current when it was
26	// acquired, so overwritten and deleted values stay readable through every
27	// view that references them. seq is the version's commit number, unique and
28	// strictly increasing along each key's chain; it orders versions across the
29	// independent chains that meet again during a pinning compaction.
30	type node struct {
31		value   []byte
32		present bool   // false marks a delete; a present nil/empty value is still a hit
33		seq     uint64 // commit order, 1-based
34		older   *node
35	}
36	
37	// view is an immutable map of keys to their newest version. Rather than
38	// copying the whole map for every commit, a view is a thin overlay: its own
39	// keys on top of a base view it never modifies. Reads descend the short chain
40	// of overlays; the current view, snapshots and cursors simply point at one.
41	//
42	// A view's keys map may itself hold the whole keyspace: the base layer
43	// (base == nil) used by recovery, compaction and periodic flattening. Maps
44	// are never mutated after publication, so reading them needs no lock; only
45	// the commit path, which has just created a fresh overlay, writes its keys.
46	type view struct {
47		keys  map[string]*node
48		base  *view
49		depth int // number of overlays from this view to its flat base
50	}
51	
52	// newView returns an empty overlay atop base (nil for a flat base view).
53	func newView(base *view) *view {
54		d := 1
55		if base != nil {
56			d = base.depth + 1
57		}
58		return &view{keys: make(map[string]*node), base: base, depth: d}
59	}
60	
61	// lookup returns the newest version recorded for key anywhere along the
62	// overlay chain, or nil when the key was never written.
63	func (v *view) lookup(key string) *node {
64		for cur := v; cur != nil; cur = cur.base {
65			if n, ok := cur.keys[key]; ok {
66				return n
67			}
68		}
69		return nil
70	}
71	
72	// rangeEach visits the terminal version of every distinct key, fn once per
73	// key, walking newest-to-oldest so an overlay entry shadows its base.
74	func (v *view) rangeEach(fn func(key string, n *node) bool) {
75		seen := make(map[string]struct{})
76		for cur := v; cur != nil; cur = cur.base {
77			for k, n := range cur.keys {
78				if _, ok := seen[k]; ok {
79					continue
80				}
81				seen[k] = struct{}{}
82				if !fn(k, n) {
83					return
84				}
85			}
86		}
87	}
88	
89	// flatten materializes one flat map holding the view's complete terminal
90	// state. It allocates a fresh map and shares only immutable nodes, so views
91	// already published stay untouched.
92	func (v *view) flatten() *view {
93		flat := newView(nil)
94		v.rangeEach(func(k string, n *node) bool {
95			flat.keys[k] = n
96			return true
97		})
98		return flat
99	}
100	
101	// Store is an open key-value store backed by a directory on disk.
102	type Store struct {
103		mu sync.Mutex // serializes writers and guards the fields below
104	
105		dir       string
106		wal       *walWriter
107		current   atomic.Pointer[view] // latest committed view; lock-free for readers
108		snapshots atomic.Uint64        // cumulative number of snapshots handed out
109		nextSeq   uint64               // highest commit sequence handed out; guarded by mu
110	
111		// chain is the in-memory record of the usable checkpoint layers paired
112		// with the current WAL, oldest first. Empty means no checkpoint is live
113		// (the next Checkpoint writes a base). Compaction re-anchors it against
114		// the replacement log; Checkpoint appends a delta and prunes the window.
115		chain []layerState
116		// dirty keys were touched by effective commits strictly after the newest
117		// layer in chain; they are exactly the keys the next delta layer covers.
118		// nil until the first such commit.
119		dirty []string
120		// legacyLive reports that a version-1 single-file snapshot.ckpt was the
121		// checkpoint paired with the WAL at open and has not been replaced by a
122		// layered chain or retired by compaction. Compaction must durably retire
123		// it before swapping the WAL, exactly as it retires a layered chain.
124		legacyLive bool
125	
126		// Open cursors pin their fixed view's versions against compaction. The
127		// set is read by Compact (which holds mu) and mutated at cursor
128		// open/close, using cursorMu; reads never take either lock.
129		cursorMu sync.Mutex
130		cursors  map[*Cursor]struct{}
131	
132		// Group-commit queue. Every state-changing commit (single Put/Delete just
133		// like CommitBatch) that arrives while another commit is forcing the log
134		// lines up here; one leader drains the queue, encodes the waiting commits
135		// and shares a single flush plus fsync across them.
136		// queueMu only ever guards this queue and committer; it is never held
137		// across disk I/O, so readers and enqueuers never wait on a sync.
138		queueMu   sync.Mutex
139		queue     []*pendingBatch
140		committer bool
141	
142		// backupMu serializes exports that stage into one chain directory
143		// (BackupIncremental) so two exports on this store never share their
144		// staging directory. It is independent of mu: it is held across the
145		// export's disk I/O and never blocks commits or lock-free reads.
146		backupMu sync.Mutex
147	
148		// Test hook, nil outside tests. leaderHook runs once after a commit has
149		// become leader, before its first queue drain, and lets tests hold a
150		// leader until a known number of commits have coalesced.
151		leaderHook func()
152	
153		closed atomic.Bool
154	}
155	
156	// Snapshot is a stable read-only view of a store captured at one instant. It
157	// owns no store resources of its own and stays usable after the store has
158	// been closed; a cursor opened from it does register with the store while it
159	// pins versions.
160	type Snapshot struct {
161		v     atomic.Pointer[view] // nil once the snapshot is closed
162		store *Store               // back-reference for cursor pin accounting
163	}
164	
165	// Open opens or creates a persistent store in dir. A path that names a
166	// regular file rather than a directory returns an error wrapping
167	// fs.ErrInvalid.
168	func Open(dir string) (*Store, error) {
169		info, err := os.Stat(dir)
170		if err == nil {
171			if !info.IsDir() {
172				return nil, errNotDir
173			}
174		} else {
175			if !errors.Is(err, fs.ErrNotExist) {
176				return nil, err
177			}
178			if err := os.MkdirAll(dir, 0o700); err != nil {
179				return nil, err
180			}
181		}
182	
183		// A replacement log from a compaction killed before its rename can never
184		// be complete state of record; the old wal.log is. Drop the stale file.
185		// Likewise, staging debris from a kill mid-checkpoint (a half-built layer
186		// temp or a legacy single-file temp) is swept: only finished layers are
187		// ever read.
188		if err := removeStaleCompact(dir); err != nil {
189			return nil, err
190		}
191		if err := sweepCheckpointDebris(dir); err != nil {
192			return nil, err
193		}
194		if err := sweepStagedChain(dir); err != nil {
195			return nil, err
196		}
197		// Sweep debris from a hot backup that was killed before its manifest, and
198		// from a restore killed before its target rename. These names never appear
199		// in a live store, so a store that was merely backed up is unaffected.
200		if err := openBackupSweep(dir); err != nil {
201			return nil, err
202		}
203		sweepRestoreDebris(dir)
204	
205		latest := newView(nil)
206		var replaySeq uint64
207		var snapshotCount uint64
208		var validSize int64
209		var chain []layerState
210		var tailTouched []string
211		var legacyLive bool
212	
213		// apply installs one replayed record into the latest view. Legacy
214		// records (written before sequence numbers existed) carry no seq; replay
215		// order is commit order, so number them sequentially.
216		apply := func(op byte, key string, value []byte, seq uint64) {
217			if seq == 0 {
218				replaySeq++
219				seq = replaySeq
220			} else if seq > replaySeq {
221				replaySeq = seq
222			}
223			switch op {
224			case opPut, opPutSeq:
225				latest.keys[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: latest.keys[key]}
226			case opDelete, opDeleteSeq:
227				latest.keys[key] = &node{present: false, seq: seq, older: latest.keys[key]}
228			}
229		}
230	
231		// Fast reopen: seed memory from the longest valid checkpoint-chain prefix
232		// and replay only the WAL written after its last layer. A layer is
233		// accepted only as a whole and only when it links to the layer before; a
234		// missing, truncated, checksum-bad, unknown-version or unlinked layer
235		// rejects it and every layer after it, and recovery falls back to the
236		// previous layer, to the legacy single-file checkpoint, or finally to a
237		// from-scratch WAL replay.
238		chainInfo, chainErr := readChain(dir)
239		if chainErr != nil {
240			return nil, chainErr
241		}
242		// Reject the suffix outright: anything beyond the longest intact, linked
243		// prefix is removed as a whole so a broken layer never pairs with the WAL
244		// and never occupies space. Half a layer is never installed.
245		pruneRejectedChainFiles(dir, len(chainInfo.layers))
246		walLen, sizeErr := walFileSize(dir)
247		if sizeErr != nil {
248			return nil, sizeErr
249		}
250		// The selected layer's cut must lie inside this exact WAL. Cuts are
251		// nondecreasing along the chain, so any suffix whose cut ran past the end
252		// of the file is rejected as a whole down to the last pairable layer.
253		for len(chainInfo.layers) > 0 && chainInfo.layers[len(chainInfo.layers)-1].offset > walLen {
254			removeRejectedChainSuffix(dir, chainInfo.layers[len(chainInfo.layers)-1].index)
255			chainInfo.layers = chainInfo.layers[:len(chainInfo.layers)-1]
256		}
257	
258		switch {
259		case len(chainInfo.layers) > 0:
260			// Compose the valid prefix: each layer overrides the one it builds on.
261			var last layerState
262			for _, l := range chainInfo.layers {
263				for _, e := range l.entries {
264					latest.keys[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
265				}
266				last = l
267			}
268			chain = chainInfo.layers
269			replaySeq = last.seq
270			// Replay the tail, remembering touched keys so the first delta layer
271			// taken in this opening also covers commits already past the cut.
272			tailApply := func(op byte, key string, value []byte, seq uint64) {
273				if op == opPut || op == opPutSeq || op == opDelete || op == opDeleteSeq {
274					tailTouched = append(tailTouched, key)
275				}
276				apply(op, key, value, seq)
277			}
278			var rerr error
279			validSize, snapshotCount, rerr = replayWALTail(dir, last.offset, last.snaps, tailApply)
280			if rerr != nil {
281				return nil, rerr
282			}
283		default:
284			// No layered chain: accept a legacy version-1 checkpoint if one is
285			// intact and pairs with this WAL, otherwise replay the whole log.
286			cp, cpOK, cpErr := loadLegacyCheckpoint(dir)
287			if cpErr != nil {
288				removeRejectedLegacy(dir)
289				cpOK = false
290			}
291			if cpOK && (cp.offset < 0 || cp.offset > walLen) {
292				removeRejectedLegacy(dir)
293				cpOK = false
294			}
295			if cpOK {
296				legacyLive = true
297				for _, e := range cp.entries {
298					latest.keys[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
299				}
300				replaySeq = cp.seq
301				validSize, snapshotCount, err = replayWALTail(dir, cp.offset, cp.snaps, apply)
302				if err != nil {
303					return nil, err
304				}
305			} else {
306				validSize, snapshotCount, err = replayWAL(dir, apply)
307				if err != nil {
308					return nil, err
309				}
310			}
311		}
312	
313		wal, err := openWALWriter(dir, validSize)
314		if err != nil {
315			return nil, err
316		}
317	
318		s := &Store{
319			dir:        dir,
320			wal:        wal,
321			cursors:    make(map[*Cursor]struct{}),
322			nextSeq:    replaySeq,
323			chain:      chain,
324			dirty:      dedupeKeys(nil, tailTouched),
325			legacyLive: legacyLive,
326		}
327		s.snapshots.Store(snapshotCount)
328		s.current.Store(latest)
329		return s, nil
330	}
331	
332	// dedupeKeys returns app's distinct keys appended to dst, first occurrence
333	// wins, preserving order.
334	func dedupeKeys(dst, src []string) []string {
335		seen := make(map[string]struct{}, len(src))
336		out := dst
337		for _, k := range src {
338			if _, ok := seen[k]; ok {
339				continue
340			}
341			seen[k] = struct{}{}
342			out = append(out, k)
343		}
344		return out
345	}
346	
347	// Put stores value under key. An empty key returns an error wrapping
348	// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
349	// key reports a hit. The store does not keep a reference to value.
350	//
351	// Put is exactly a one-op batch: it joins the same group-commit queue as
352	// CommitBatch, so a single write and concurrent batches can share one disk
353	// sync while each keeps its own crash atomicity.
354	func (s *Store) Put(key string, value []byte) error {
355		if s.closed.Load() {
356			return errStoreClosed
357		}
358		if key == "" {
359			return errEmptyKey
360		}
361		return s.commit([]BatchOp{{Key: key, Value: value}})
362	}
363	
364	// Delete removes key. Deleting an empty key returns an error wrapping
365	// fs.ErrInvalid; deleting a key that was never written or is already deleted
366	// is not an error and commits nothing. It joins the same group-commit queue a
367	// batch uses.
368	func (s *Store) Delete(key string) error {
369		if s.closed.Load() {
370			return errStoreClosed
371		}
372		if key == "" {
373			return errEmptyKey
374		}
375		return s.commit([]BatchOp{{Key: key, Delete: true}})
376	}
377	
378	type pendingBatch struct {
379		ops  []BatchOp
380		done chan error // buffered(1); the leader delivers the commit result
381	}
382	
383	// commitPlan is one queued batch resolved against the cumulative state built
384	// up across its whole sync group.
385	type commitPlan struct {
386		view  *view // cumulative view after this batch; nil when it committed nothing
387		dirty []string
388	}
389	
390	// BatchOp is one change in a batch committed with CommitBatch. Delete false
391	// stores Value under Key (a nil or empty Value is still a hit); Delete true
392	// removes Key.
393	type BatchOp struct {
394		Key    string
395		Value  []byte
396		Delete bool
397	}
398	
399	// commit enqueues ops as one atomic framed commit and drives the leader loop.
400	// Single-key Put/Delete and CommitBatch are all this one path.
401	func (s *Store) commit(ops []BatchOp) error {
402		if s.closed.Load() {
403			return errStoreClosed
404		}
405		if err := validateBatchOps(ops); err != nil {
406			return err
407		}
408	
409		me := &pendingBatch{ops: ops, done: make(chan error, 1)}
410	
411		// Enqueue. queueMu guards only the queue and the leader flag and is
412		// never held across disk I/O, so followers can join a group while the
413		// leader is syncing and readers never wait.
414		s.queueMu.Lock()
415		if s.closed.Load() {
416			s.queueMu.Unlock()
417			return errStoreClosed
418		}
419		s.queue = append(s.queue, me)
420		if s.committer {
421			s.queueMu.Unlock()
422			return <-me.done // the running leader will drain this batch
423		}
424		s.committer = true
425		s.queueMu.Unlock()
426	
427		// Test-only rendezvous: invoked once by the elected leader before its
428		// first queue drain. Production leaves it nil.
429		if s.leaderHook != nil {
430			s.leaderHook()
431		}
432	
433		// Leadership: drain groups until the queue is empty. Each group takes
434		// s.mu while it forces the log, which serializes it with Snapshot,
435		// Checkpoint, Compact and Close, so a group never straddles a log swap or
436		// a layer capture.
437		for {
438			s.queueMu.Lock()
439			// Resign and re-check the queue under one critical section, so a
440			// batch enqueuing in this instant either observes the still-active
441			// leader or becomes the next one; no batch can be left queued with
442			// no leader to drain it.
443			if len(s.queue) == 0 {
444				s.committer = false
445				s.queueMu.Unlock()
446				break
447			}
448			group := s.queue
449			s.queue = nil
450			s.queueMu.Unlock()
451			for p, rerr := range s.commitGroup(group) {
452				group[p].done <- rerr
453			}
454		}
455	
456		return <-me.done
457	}
458	
459	// CommitBatch applies a group of writes and deletes as one atomic commit:
460	// the whole batch becomes visible together or not at all, and snapshots and
461	// cursors fixed at any instant see either the state before the batch or the
462	// state after it, never an in-between mixture. Changes are applied in list
463	// order; a later change to the same key overrides an earlier one within the
464	// batch. Concurrent batches take effect in commit (enqueue) order, and a
465	// later committed batch's same-key change overrides an earlier one's.
466	//
467	// Batches committed concurrently (with single Put/Delete calls among them)
468	// share the disk sync: one leader drains the queue, encodes every waiting
469	// commit as its own recoverable framed commit and forces them all with one
470	// flush plus fsync, so N commits arriving together cost one sync while each
471	// stays whole on recovery; a commit that arrives while a sync is in flight
472	// rides the next one. Reads take none of these locks and are never blocked by
473	// the sync.
474	//
475	// If any change has an empty key the whole batch is rejected before it is
476	// queued or committed: an error wrapping fs.ErrInvalid is returned, no frame
477	// is written and the store's state is unchanged. A delete of a key that is
478	// absent or already deleted commits nothing, exactly like Delete; a batch
479	// containing only such no-ops (or an empty slice) commits nothing and
480	// returns nil. CommitBatch on a closed store returns an error wrapping
481	// fs.ErrClosed.
482	//
483	// Each batch is forced to stable storage before its call returns and is
484	// published as one new view; a process killed mid-commit therefore reopens
485	// with the entire batch present or entirely absent. The store does not keep
486	// references to the op Value slices after return.
487	func (s *Store) CommitBatch(ops []BatchOp) error {
488		return s.commit(ops)
489	}
490	
491	// validateBatchOps checks argument-only invariants before a batch is queued.
492	// Empty keys map to fs.ErrInvalid, exactly as for Put and Delete.
493	func validateBatchOps(ops []BatchOp) error {
494		for i := range ops {
495			if ops[i].Key == "" {
496				return errEmptyKey
497			}
498		}
499		for i := range ops {
500			if len(ops[i].Key) > maxRecord || (!ops[i].Delete && seqSize+len(ops[i].Value) > maxRecord) {
501				return errRecordTooLarge()
502			}
503		}
504		return nil
505	}
506	
507	func errRecordTooLarge() error { return errors.New("snapshot: record too large") }
508	
509	// commitGroup encodes and forces every queued batch with one flush and one
510	// sync, then publishes one view per effective batch in queue (commit) order.
511	// It returns one result per batch. An encoding or sync failure fails the
512	// whole group: nothing it contained is published or sequenced. The single
513	// committer calls this; s.mu is taken for the entire force, exactly as the
514	// view transitions and checkpoint watermarks need.
515	func (s *Store) commitGroup(group []*pendingBatch) []error {
516		results := make([]error, len(group))
517	
518		s.mu.Lock()
519		defer s.mu.Unlock()
520		if s.closed.Load() || s.wal == nil {
521			// Close ran between the drain and the lock; nothing can commit.
522			for i := range results {
523				results[i] = errStoreClosed
524			}
525			return results
526		}
527	
528		// Remember where the group starts so any failure can rewind the log:
529		// unacknowledged frames must not linger at EOF and reappear under a
530		// later commit or after a reopen. Nothing is buffered here (the previous
531		// group always flushed), so EOF is the exact offset.
532		groupStart, posErr := s.wal.position()
533		if posErr != nil {
534			for i := range results {
535				results[i] = posErr
536			}
537			return results
538		}
539		rollback := func(cause error) []error {
540			if err := s.wal.truncateTo(groupStart); err != nil {
541				cause = errors.Join(cause, err)
542			}
543			for i := range results {
544				results[i] = cause
545			}
546			return results
547		}
548	
549		base := s.current.Load()
550		seq := s.nextSeq
551		plans := make([]commitPlan, 0, len(group))
552		encodedAny := false
553		var groupDirty []string
554	
555		// head caches the group-cumulative terminal node of every key the queued
556		// batches touch: a nil entry means "known absent in base". It is sized by
557		// the batches' distinct keys, never by the live keyspace. The baseline
558		// flattened the whole view inside this loop every viewFlattenLimit queued
559		// batches, so a long queue behind one sync copied the live keyspace once
560		// per viewFlattenLimit batches; now each touched key walks the (already
561		// bounded) overlay chain at most once and at most one full keyspace map is
562		// built per group, after the last overlay.
563		head := make(map[string]*node)
564		resolve := func(key string) *node {
565			if n, ok := head[key]; ok {
566				return n // nil records a key known to be absent
567			}
568			n := base.lookup(key)
569			head[key] = n
570			return n
571		}
572	
573		for _, p := range group {
574			// Each batch gets its own thin immutable overlay on the previous
575			// batch's overlay, so the view it publishes is a valid point-in-time
576			// state independent of later batches, and queued batches cost memory
577			// proportional to their own ops rather than the whole live keyspace.
578			v := newView(base)
579			var changes []batchChange
580			for i := range p.ops {
581				op := &p.ops[i]
582				headNode := resolve(op.Key)
583				if op.Delete {
584					if headNode == nil || !headNode.present {
585						continue // idempotent no-op, matching the single Delete
586					}
587					seq++
588					nn := &node{present: false, seq: seq, older: headNode}
589					changes = append(changes, batchChange{key: op.Key, seq: seq, delete: true})
590					v.keys[op.Key] = nn
591					head[op.Key] = nn
592				} else {
593					seq++
594					value := cloneBytes(op.Value)
595					nn := &node{value: value, present: true, seq: seq, older: headNode}
596					changes = append(changes, batchChange{key: op.Key, seq: seq, value: value})
597					v.keys[op.Key] = nn
598					head[op.Key] = nn
599				}
600			}
601			if len(changes) > 0 {
602				if err := s.wal.encodeBatch(changes); err != nil {
603					return rollback(err)
604				}
605				encodedAny = true
606				for i := range changes {
607					groupDirty = append(groupDirty, changes[i].key)
608				}
609			}
610			var planView *view
611			if len(changes) > 0 {
612				planView = v
613			}
614			plans = append(plans, commitPlan{view: planView})
615			base = v
616		}
617	
618		if encodedAny {
619			// One flush, one fsync for the whole group. Return means every
620			// encoded batch in it is durable as a self-contained framed commit.
621			if err := s.wal.flushSync(); err != nil {
622				return rollback(err)
623			}
624		}
625	
626		s.nextSeq = seq
627		// Publish one view per effective batch in queue order, so each batch's
628		// state becomes observable atomically as its own point-in-time view. Then,
629		// whenever the chain reached the depth bound, publish one flattened final
630		// view. That flatten builds one full keyspace map at most (after the last
631		// overlay) and keeps read depth and the next group's baseline bounded by
632		// viewFlattenLimit rather than by queue length; the baseline built one full
633		// map per viewFlattenLimit queued batches inside the loop.
634		var finalFlat *view
635		if base.depth >= viewFlattenLimit {
636			finalFlat = base.flatten()
637		}
638		for _, plan := range plans {
639			if plan.view != nil {
640				s.current.Store(plan.view)
641			}
642		}
643		if finalFlat != nil {
644			s.current.Store(finalFlat)
645		}
646		s.dirty = dedupeKeys(s.dirty, groupDirty)
647		return results
648	}
649	
650	// Get returns the latest committed value for key. Empty keys, keys never
651	// written and deleted keys are all misses: ok is false and err is nil. The
652	// returned bytes are owned by the caller.
653	func (s *Store) Get(key string) ([]byte, bool, error) {
654		if s.closed.Load() {
655			return nil, false, errStoreClosed
656		}
657		if key == "" {
658			return nil, false, nil
659		}
660		val, ok := lookupView(s.current.Load(), key)
661		return val, ok, nil
662	}
663	
664	// Compact reclaims history: values that were overwritten or deleted and are
665	// not needed by any open snapshot or cursor are dropped from memory and the
666	// write-ahead log is atomically rewritten, so the directory occupies less
667	// space than before whenever reclaimable history existed.
668	//
669	// When a checkpoint chain is live, compaction keeps the generations inside
670	// the retention window and re-anchors them against the replacement log: that
671	// log is written as one segment per surviving layer (its prefix reproducing
672	// the layer's terminal state at a fresh cut), followed by the post-window
673	// changes and the snapshot-count meta, and the rebuilt layers reference those
674	// cuts. Generations outside the window are retired together with the old
675	// chain and stop occupying space immediately.
676	//
677	// Every open snapshot keeps its exact fixed view; every open cursor keeps
678	// paging through its exact fixed sequence, and the one version per key its
679	// view shows stays in the rewritten log until the cursor closes; the next
680	// compaction then reclaims it and shrinks the directory further. A process
681	// killed at any point during compaction reopens in a complete commit state,
682	// with every successful write, deletion and the cumulative snapshot count
683	// intact; no intermediate file needs a second compaction or checkpoint to
684	// repair.
685	//
686	// Compact serializes with writes, deletes, snapshots, cursor opens, closing
687	// and other compactions (the group-commit leader and every other mutator
688	// take the same lock); concurrent or repeated calls queue and all return nil.
689	// Compacting a closed store returns an error wrapping fs.ErrClosed.
690	func (s *Store) Compact() error {
691		s.mu.Lock()
692		defer s.mu.Unlock()
693		if s.closed.Load() {
694			return errStoreClosed
695		}
696	
697		cur := s.current.Load()
698	
699		// Pinned versions, keyed by commit sequence (globally unique). The
700		// current head of every live key in the latest view is retained; each
701		// open cursor additionally pins the single head version its fixed view
702		// shows for every present key in its range. A deleted key's tombstone is
703		// retained only when a cursor still reads an older value under it, so
704		// replay links that value as the tombstone's predecessor; otherwise the
705		// key is dropped from the rewritten log altogether, as before.
706		pinned := make(map[uint64]*node)
707		keySeqs := make(map[string][]uint64)
708		cursorPins := make(map[string]bool)
709		pin := func(k string, n *node) {
710			if n == nil {
711				return
712			}
713			if _, ok := pinned[n.seq]; !ok {
714				pinned[n.seq] = n
715				keySeqs[k] = append(keySeqs[k], n.seq)
716			}
717		}
718		for _, c := range s.openCursors() {
719			for _, k := range c.keys {
720				cursorPins[k] = true
721				pin(k, c.v.lookup(k)) // exactly the version this cursor pages out
722			}
723		}
724		for k, n := range keySetOf(cur) {
725			if n.present || cursorPins[k] {
726				pin(k, n) // live head, or a tombstone shielding a pinned value
727			}
728		}
729	
730		plan := buildCompactionPlan(pinned, keySeqs)
731		snapshotCount := s.snapshots.Load()
732	
733		// The surviving window, oldest first. Layers before it are retired.
734		window := checkpointWindow
735		if window > len(s.chain) {
736			window = len(s.chain)
737		}
738		first := len(s.chain) - window
739		windowLayers := s.chain[first:]
740		hadChain := len(s.chain) > 0
741		// paired reports any checkpoint — layered chain or a legacy single file —
742		// whose cut belongs to the WAL about to be replaced. It must be withdrawn
743		// before the swap so no checkpoint is ever read against a different log.
744		paired := hadChain || s.legacyLive
745	
746		// Phase 1 (nothing live is touched yet): build and sync the complete
747		// replacement log, and when layers survive, the matching staged chain.
748		// Any failure here removes the staged files and leaves the store and the
749		// old WAL/chain exactly as they were, so committing can continue.
750		var seg *segmentedWAL
751		if !hadChain {
752			if err := buildCompactWAL(s.dir, plan.histories(), snapshotCount); err != nil {
753				return err
754			}
755		} else {
756			// Full terminal state at each window layer's watermark, composed from
757			// the complete old chain (including the generations about to retire).
758			termStates := make([][]checkpointEntry, window)
759			for w := 0; w < window; w++ {
760				termStates[w] = composeLayers(s.chain[:first+w+1])
761			}
762			seg = planSegmentedWAL(plan, windowLayers, termStates, cur)
763			if err := buildSegmentedCompactArtifacts(s.dir, seg, snapshotCount); err != nil {
764				return err
765			}
766		}
767	
768		// Phase 2: the replacement must never meet a paired checkpoint on reopen.
769		// Durably withdraw the whole layered chain and/or the legacy file while
770		// the old wal.log is still in place; a crash after this but before the
771		// rename simply replays the old log in full. Failure precedes any
772		// stateful move, so drop the staged files and leave the store untouched.
773		if paired {
774			if err := retireChain(s.dir); err != nil {
775				removeStaleCompact(s.dir)
776				removeStagedChain(s.dir)
777				return err
778			}
779			s.legacyLive = false
780		}
781		oldWAL := s.wal
782		if err := oldWAL.close(); err != nil {
783			// Staged files have not become state of record; remove them and
784			// reopen a writer on the untouched old log, so no repair-only
785			// intermediate lingers and the next commit proceeds.
786			removeStaleCompact(s.dir)
787			removeStagedChain(s.dir)
788			reopened, openErr := openWALWriter(s.dir, -1)
789			if openErr != nil {
790				return err
791			}
792			s.wal = reopened
793			return err
794		}
795		// Phase 3: atomically rename the temp over wal.log, force the directory
796		// and open a writer on the new log. If the rename never landed the old
797		// log is intact and committing continues (staged chain is dropped).
798		nextWAL, renamed, installErr := installCompactWAL(s.dir)
799		if nextWAL == nil {
800			// The rename landed but the new log cannot be opened: the directory
801			// is not in a state where further commits are safe, so mark the
802			// store closed rather than leaving a handle only another compaction
803			// could repair.
804			s.closed.Store(true)
805			s.wal = nil
806			return installErr
807		}
808		s.wal = nextWAL
809		if renamed {
810			s.current.Store(plan.freshView())
811			if hadChain {
812				// dropCheckpoint clears any in-memory and on-disk chain so the
813				// next Checkpoint starts a fresh base with no O_EXCL collision.
814				dropCheckpoint := func() {
815					s.chain = nil
816					s.dirty = nil
817					os.RemoveAll(checkpointDirPath(s.dir))
818				}
819				if window == 0 {
820					dropCheckpoint()
821					removeStagedChain(s.dir)
822				} else if err := activateStagedChain(s.dir); err != nil {
823					// The new WAL is already live; rather than leave a half
824					// installed chain, run with no live checkpoint. The next
825					// Checkpoint establishes a fresh base.
826					dropCheckpoint()
827				} else {
828					info, ierr := readChain(s.dir)
829					if ierr != nil || len(info.layers) != window {
830						dropCheckpoint()
831					} else {
832						s.chain = info.layers
833						s.dirty = seg.tailKeys
834					}
835				}
836			}
837		} else if hadChain {
838			// Rename failed; the old WAL stayed. retireChain already removed the
839			// old chain, so drop the staged replacement as well: no checkpoint
840			// pairs with this WAL. Committing continues; the next Checkpoint heals.
841			removeStagedChain(s.dir)
842			s.chain = nil
843			s.dirty = nil
844		}
845		return installErr
846	}
