848	// keySetOf returns the distinct keys present anywhere in the view.
849	func keySetOf(v *view) map[string]*node {
850		out := make(map[string]*node)
851		v.rangeEach(func(k string, n *node) bool {
852			out[k] = n
853			return true
854		})
855		return out
856	}
857	
858	// Checkpoint appends one self-describing, checksummed layer to the checkpoint
859	// chain so the next Open seeds memory from the longest intact layer prefix
860	// and replays only the write-ahead log written after it, instead of replaying
861	// the whole log. The first layer (the base) holds complete committed state;
862	// every later layer covers only commits after the layer it builds on.
863	// Checkpoint changes nothing visible: every committed write and deletion, the
864	// cumulative snapshot count and every open snapshot or cursor are unaffected,
865	// and reads keep hitting memory without touching disk.
866	//
867	// Producing a layer and making it live are two distinct steps: the layer is
868	// captured under the write lock, built fully under a temporary name and
869	// forced to stable storage, then atomically renamed into place and linked to
870	// the previous layer by a content hash. A kill at any instant leaves either
871	// the old complete chain or the chain extended by one complete layer; reopen
872	// observes one complete committed state, never a half layer (staging debris
873	// is swept on the next open).
874	//
875	// Only checkpointWindow newest generations are kept: appending past the
876	// window rebuilds the chain with the oldest surviving layer as a fresh full
877	// base against the unchanged WAL and deletes the retired layers immediately.
878	//
879	// Checkpoint serializes with writes, batch commits, snapshots, cursor opens,
880	// compaction and closing (it takes the same write lock), but never with
881	// lock-free reads: Get, scans, snapshot reads and cursor paging proceed while
882	// it runs. A batch stays wholly on one side of the captured cut, and history
883	// pinned by open snapshots or cursors is left untouched. On a closed store
884	// Checkpoint returns an error wrapping fs.ErrClosed.
885	func (s *Store) Checkpoint() error {
886		s.mu.Lock()
887		defer s.mu.Unlock()
888		if s.closed.Load() {
889			return errStoreClosed
890		}
891	
892		offset, err := s.wal.position()
893		if err != nil {
894			return err
895		}
896		cur := s.current.Load()
897		snaps := s.snapshots.Load()
898	
899		if len(s.chain) == 0 {
900			// First layer: full base state. This also upgrades a legacy
901			// single-file directory: the old file is removed once the base is
902			// staged, and the WAL it pairs with has not changed.
903			layer := capturedLayer{
904				index:   0,
905				entries: captureView(cur),
906				offset:  uint64(offset),
907				seq:     s.nextSeq,
908				snaps:   snaps,
909			}
910			if err := installLayer(s.dir, layer); err != nil {
911				return err
912			}
913			if err := removeLegacyCheckpoint(s.dir); err != nil {
914				return err
915			}
916			s.legacyLive = false
917		} else {
918			last := s.chain[len(s.chain)-1]
919			layer := capturedLayer{
920				index:   last.index + 1,
921				prevCRC: last.crc,
922				entries: captureDelta(cur, s.dirty),
923				offset:  uint64(offset),
924				seq:     s.nextSeq,
925				snaps:   snaps,
926			}
927			if err := installLayer(s.dir, layer); err != nil {
928				return err
929			}
930		}
931	
932		info, err := readChain(s.dir)
933		if err != nil {
934			return err
935		}
936		s.chain = info.layers
937		s.dirty = nil
938	
939		// Enforce the retention window: keep only the newest checkpointWindow
940		// layers, rebuilt as a standalone chain against the same unchanged WAL.
941		if len(s.chain) > checkpointWindow {
942			if err := s.rebaseChainToWindow(); err != nil {
943				return err
944			}
945		}
946		return nil
947	}
948	
949	// rebaseChainToWindow rebuilds the live chain so only the newest
950	// checkpointWindow layers remain: the oldest kept layer becomes a fresh full
951	// base (materialized from the complete in-memory chain) at its existing WAL
952	// cut, and the layers after it keep their delta content at their existing
953	// cuts. The WAL is not touched.
954	func (s *Store) rebaseChainToWindow() error {
955		keep := checkpointWindow
956		if keep > len(s.chain) {
957			keep = len(s.chain)
958		}
959		first := len(s.chain) - keep
960		// Materialize full terminal state at the oldest kept layer.
961		full := composeLayers(s.chain[:first+1])
962		newLayers := make([]capturedLayer, 0, keep)
963		newLayers = append(newLayers, capturedLayer{
964			index: 0, entries: full,
965			offset: uint64(s.chain[first].offset),
966			seq:    s.chain[first].seq,
967			snaps:  s.chain[first].snaps,
968		})
969		for j := first + 1; j < len(s.chain); j++ {
970			newLayers = append(newLayers, capturedLayer{
971				index:   uint32(j - first),
972				entries: s.chain[j].entries,
973				offset:  uint64(s.chain[j].offset),
974				seq:     s.chain[j].seq,
975				snaps:   s.chain[j].snaps,
976			})
977		}
978		if err := replaceCheckpointChain(s.dir, newLayers); err != nil {
979			return err
980		}
981		info, err := readChain(s.dir)
982		if err != nil {
983			return err
984		}
985		s.chain = info.layers
986		return nil
987	}
988	
989	// composeLayers returns the full terminal state after applying layers in
990	// order (each overriding the one before), sorted by key for a canonical base.
991	func composeLayers(layers []layerState) []checkpointEntry {
992		term := make(map[string]checkpointEntry)
993		for _, l := range layers {
994			for _, e := range l.entries {
995				term[e.key] = e // later layer wins; tombstones survive as tombstones
996			}
997		}
998		out := make([]checkpointEntry, 0, len(term))
999		for _, e := range term {
1000			out = append(out, e)
1001		}
1002		sortEntries(out)
1003		return out
1004	}
1005	
1006	// openCursors snapshots the set of currently open cursors. Cursor views and
1007	// bounds are immutable after opening, so reading their fields here needs no
1008	// per-cursor lock.
1009	func (s *Store) openCursors() []*Cursor {
1010		s.cursorMu.Lock()
1011		defer s.cursorMu.Unlock()
1012		cs := make([]*Cursor, 0, len(s.cursors))
1013		for c := range s.cursors {
1014			cs = append(cs, c)
1015		}
1016		return cs
1017	}
1018	
1019	// Snapshot acquires a stable view. It never observes writes committed after
1020	// it returns, and keeps serving that view regardless of later writes,
1021	// deletes or Store.Close, until the Snapshot itself is closed.
1022	func (s *Store) Snapshot() (*Snapshot, error) {
1023		s.mu.Lock()
1024		defer s.mu.Unlock()
1025		if s.closed.Load() {
1026			return nil, errStoreClosed
1027		}
1028		count := s.snapshots.Add(1)
1029		if err := s.wal.appendMeta(count); err != nil {
1030			s.snapshots.Add(^uint64(0))
1031			return nil, err
1032		}
1033		snap := &Snapshot{store: s}
1034		snap.v.Store(s.current.Load())
1035		return snap, nil
1036	}
1037	
1038	// Get reads key from the snapshot's fixed view. Old values overwritten or
1039	// deleted afterwards are still readable; keys created afterwards, empty
1040	// keys and keys absent or deleted when the snapshot was taken are misses. A
1041	// read from a closed snapshot is also a plain miss, never an error. The
1042	// returned bytes are owned by the caller.
1043	func (s *Snapshot) Get(key string) ([]byte, bool) {
1044		if key == "" {
1045			return nil, false
1046		}
1047		v := s.v.Load()
1048		if v == nil {
1049			return nil, false // closed snapshot
1050		}
1051		n := v.lookup(key)
1052		if n == nil || !n.present {
1053			return nil, false
1054		}
1055		return cloneBytes(n.value), true
1056	}
1057	
1058	// Close releases the snapshot's fixed view. Closing more than once is a
1059	// no-op returning nil.
1060	func (s *Snapshot) Close() error {
1061		s.v.Store(nil)
1062		return nil
1063	}
1064	
1065	// Close flushes and closes the store. Data already committed stays complete
1066	// and readable after reopening the directory. Snapshots still open keep
1067	// serving their fixed views until closed themselves; closing an already
1068	// closed store is a no-op returning nil.
1069	func (s *Store) Close() error {
1070		s.mu.Lock()
1071		if !s.closed.CompareAndSwap(false, true) {
1072			s.mu.Unlock()
1073			return nil
1074		}
1075		wal := s.wal
1076		s.wal = nil
1077		s.mu.Unlock()
1078	
1079		return wal.close()
1080	}
1081	
1082	func lookupView(v *view, key string) ([]byte, bool) {
1083		n := v.lookup(key)
1084		if n == nil || !n.present {
1085			return nil, false
1086		}
1087		return cloneBytes(n.value), true
1088	}
1089	
1090	func cloneBytes(b []byte) []byte {
1091		if b == nil {
1092			return nil
1093		}
