363			if err := s.BackupIncremental(chain); err != nil {
364				t.Fatalf("concurrent incremental: %v", err)
365			}
366			rings = append(rings, copyChain(t, chain))
367		}
368		close(stop)
369		wg.Wait()
370	
371		first, err := Restore(rings[0], filepath.Join(t.TempDir(), "a"))
372		if err != nil {
373			t.Fatal(err)
374		}
375		p1 := allPairs(t, first)
376		first.Close()
377		first2, err := Restore(rings[0], filepath.Join(t.TempDir(), "b"))
378		if err != nil {
379			t.Fatal(err)
380		}
381		p2 := allPairs(t, first2)
382		first2.Close()
383		assertSamePairs(t, p1, p2, "deterministic fixed-watermark restore")
384	
385		// Final chain is internally consistent.
386		tip, err := Restore(chain, filepath.Join(t.TempDir(), "tip"))
387		if err != nil {
388			t.Fatal(err)
389		}
390		pairs := allPairs(t, tip)
391		for i := 1; i < len(pairs); i++ {
392			if pairs[i].Key <= pairs[i-1].Key {
393				t.Fatal("restored pairs not strictly ordered")
394			}
395		}
396		tip.Close()
397	}
