package snapshot

import (
	"bufio"
	"container/heap"
	"encoding/binary"
	"errors"
	"hash/crc32"
	"io"
	"os"
	"path/filepath"
	"sort"
)

// On-demand backup-chain merging.
//
// A backup chain only grows: one full head followed by dense incremental
// rings. MergeChain folds the head together with the first rings rings of the
// chain into one fresh full head capturing the complete committed state at
// that last ring's watermark; every surviving ring stays on the chain, renamed
// into a dense 1-based sequence linked to the new head. The merged chain is
// byte-for-byte equivalent at its tip to the old chain through that
// watermark, and Restore keeps validating it as one whole.
//
// Merge debris lives next to the chain directory, never inside it while the
// merge runs:
//
//	<base>.merge.tmp/   staging directory holding the complete new chain
//	<base>.merge.obs    old chain directory across the atomic swap
//
// The merge streams a k-way merge over the artifacts (one head source that
// opens its segments lazily plus one source per folded ring) and never copies
// the whole keyspace into memory before writing. The swap is two directory
// renames: the live chain is renamed aside and the fully synced staging
// directory is renamed into its place. A kill at any instant therefore leaves
// either the old chain or the complete new chain; sweepMergeArtifacts heals a
// kill between the two renames by renaming the old chain back, and removes
// staging debris at the next merge, backup into that directory or open of a
// related directory.
//
// The merge reads artifacts only: the store that produced the chain is never
// modified, and MergeChain takes no store lock, so writes, batch commits,
// snapshot open/close, cursor paging, checkpoints, compaction and lock-free
// reads all proceed while it runs. Exports issued by the same store serialize
// with the merge on backupMu, so an incremental export and a merge can never
// install over each other or leave half a ring or half a chain.

const (
	mergeStageSuffix = ".merge.tmp"
	mergeObsSuffix   = ".merge.obs"
)

func mergeStagePath(parent, base string) string {
	return filepath.Join(parent, base+mergeStageSuffix)
}

func mergeObsPath(parent, base string) string {
	return filepath.Join(parent, base+mergeObsSuffix)
}

// mergeEntry is one terminal key state streamed out of an artifact.
type mergeEntry struct {
	key   string
	flag  byte
	value []byte
	seq   uint64
}

// mergeSource streams entries of one artifact in strictly ascending key
// order. Entries are validated as they are read, the same way Restore
// validates them; a defect surfaces as errBadBackup and rejects the merge
// before the chain is touched.
type mergeSource interface {
	read() (mergeEntry, error) // io.EOF at a fully consumed, intact artifact
	close()
}

// headMergeSource streams the full head. Its segment files are opened lazily
// one at a time, so a head of any segment count costs one open file (and one
// bounded read buffer), not one per segment.
type headMergeSource struct {
	dir  string
	head manifestInfo
	seg  int
	f    *os.File
	r    *bufio.Reader
	h    interface { // current segment content hash
		Write(p []byte) (int, error)
		Sum32() uint32
	}
	remaining uint32 // entries left in the open segment
	seen      uint64 // entries streamed across segments
	lastKey   string
	haveKey   bool
}

func newHeadMergeSource(dir string, head manifestInfo) *headMergeSource {
	return &headMergeSource{dir: dir, head: head}
}

func (m *headMergeSource) close() {
	if m.f != nil {
		m.f.Close()
		m.f = nil
	}
}

// openNextSegment opens and validates the header of the next head segment.
func (m *headMergeSource) openNextSegment() error {
	if m.f != nil {
		m.f.Close()
		m.f = nil
	}
	seg := m.head.segments[m.seg]
	f, err := os.Open(filepath.Join(m.dir, segmentName(seg.index)))
	if err != nil {
		return err
	}
	m.f = f
	m.r = bufio.NewReader(f)
	hdr := make([]byte, backupSegHeaderSize)
	if err := readFull(m.r, hdr); err != nil {
		return err
	}
	h := crc32.NewIEEE()
	h.Write(hdr)
	m.h = h
	if binary.LittleEndian.Uint32(hdr[0:4]) != backupMagic ||
		binary.LittleEndian.Uint32(hdr[4:8]) != backupVersion ||
		binary.LittleEndian.Uint64(hdr[8:16]) != m.head.watermark ||
		binary.LittleEndian.Uint64(hdr[16:24]) != m.head.snaps ||
		binary.LittleEndian.Uint32(hdr[24:28]) != seg.index ||
		binary.LittleEndian.Uint32(hdr[28:32]) != seg.count ||
		binary.LittleEndian.Uint64(hdr[32:40]) != seg.cumulative {
		return errBadBackup
	}
	m.remaining = seg.count
	return nil
}

func (m *headMergeSource) read() (mergeEntry, error) {
	var zero mergeEntry
	for m.remaining == 0 {
		if m.f != nil {
			// Finish the consumed segment: its terminal CRC must verify.
			var crcb [crcSize]byte
			if err := readFull(m.r, crcb[:]); err != nil {
				return zero, err
			}
			seg := m.head.segments[m.seg]
			if binary.LittleEndian.Uint32(crcb[:]) != m.h.Sum32() ||
				binary.LittleEndian.Uint32(crcb[:]) != seg.crc {
				return zero, errBadBackup
			}
			if _, err := m.r.ReadByte(); !errors.Is(err, io.EOF) {
				return zero, errBadBackup
			}
			m.f.Close()
			m.f = nil
			m.seg++
		}
		if m.seg >= len(m.head.segments) {
			if m.seen != m.head.total {
				return zero, errBadBackup
			}
			return zero, io.EOF
		}
		if err := m.openNextSegment(); err != nil {
			return zero, err
		}
	}

	ehdr := make([]byte, checkpointEntrySize)
	if err := readFull(m.r, ehdr); err != nil {
		return zero, err
	}
	m.h.Write(ehdr)
	flag := ehdr[0]
	keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
	valLen := binary.LittleEndian.Uint32(ehdr[5:9])
	seq := binary.LittleEndian.Uint64(ehdr[9:17])
	if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
		keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
		(flag == ckptFlagDelete && valLen != 0) ||
		seq == 0 || seq > m.head.watermark {
		return zero, errBadBackup
	}
	body := make([]byte, int(keyLen)+int(valLen))
	if err := readFull(m.r, body); err != nil {
		return zero, err
	}
	m.h.Write(body)
	key := string(body[:keyLen])
	if m.haveKey && key <= m.lastKey {
		return zero, errBadBackup
	}
	m.lastKey, m.haveKey = key, true
	m.remaining--
	m.seen++
	return mergeEntry{key: key, flag: flag, value: body[keyLen:], seq: seq}, nil
}

// ringMergeSource streams one folded ring, validating its header, segments,
// footer and terminal file CRC exactly as scanRing does, one entry at a time.
type ringMergeSource struct {
	f       *os.File
	r       *bufio.Reader
	hf      interface {
		Write(p []byte) (int, error)
		Sum32() uint32
	}
	hs interface {
		Write(p []byte) (int, error)
		Sum32() uint32
	}

	index    uint32
	segCount uint32
	seg      uint32
	startWM  uint64
	endWM    uint64

	remaining uint32 // entries left in the open segment
	total     uint64
	segChain  uint32
	lastKey   string
	haveKey   bool
	checked   bool // footer/EOF already verified
}

func newRingMergeSource(path string, exp ringExpect) (*ringMergeSource, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	m := &ringMergeSource{f: f, r: bufio.NewReader(f)}
	hf := crc32.NewIEEE()
	m.hf = hf

	read := func(buf []byte) error {
		if err := readFull(m.r, buf); err != nil {
			return err
		}
		hf.Write(buf)
		return nil
	}

	head := make([]byte, incrRingHeaderSize)
	if err := read(head); err != nil {
		m.close()
		return nil, err
	}
	if binary.LittleEndian.Uint32(head[0:4]) != backupMagic ||
		binary.LittleEndian.Uint32(head[4:8]) != backupVersion {
		m.close()
		return nil, errBadBackup
	}
	m.index = binary.LittleEndian.Uint32(head[8:12])
	prevLink := binary.LittleEndian.Uint32(head[12:16])
	m.startWM = binary.LittleEndian.Uint64(head[16:24])
	m.endWM = binary.LittleEndian.Uint64(head[24:32])
	snaps := binary.LittleEndian.Uint64(head[32:40])
	m.segCount = binary.LittleEndian.Uint32(head[40:44])
	if m.index != exp.index || prevLink != exp.prevLink || m.startWM != exp.startWM ||
		m.endWM < m.startWM || m.segCount > backupMaxSegments {
		m.close()
		return nil, errBadBackup
	}
	_ = snaps
	return m, nil
}

func (m *ringMergeSource) close() {
	if m.f != nil {
		m.f.Close()
		m.f = nil
	}
}

// openNextSegment reads and validates the next segment header.
func (m *ringMergeSource) openNextSegment() error {
	shdr := make([]byte, incrSegHeaderSize)
	if err := readFull(m.r, shdr); err != nil {
		return err
	}
	m.hf.Write(shdr)
	hs := crc32.NewIEEE()
	hs.Write(shdr)
	m.hs = hs
	if binary.LittleEndian.Uint32(shdr[0:4]) != backupMagic ||
		binary.LittleEndian.Uint64(shdr[4:12]) != m.startWM ||
		binary.LittleEndian.Uint64(shdr[12:20]) != m.endWM ||
		binary.LittleEndian.Uint32(shdr[20:24]) != m.index ||
		binary.LittleEndian.Uint32(shdr[24:28]) != m.seg {
		return errBadBackup
	}
	count := binary.LittleEndian.Uint32(shdr[28:32])
	if count == 0 || count > maxRecord {
		return errBadBackup
	}
	// The segment's cumulative count is checked when its terminal CRC is read;
	// track it through m.total like scanRing does.
	m.remaining = count
	return nil
}

func (m *ringMergeSource) readByteCRC() error {
	var crcb [crcSize]byte
	if err := readFull(m.r, crcb[:]); err != nil {
		return err
	}
	m.hf.Write(crcb[:])
	return nil
}

func (m *ringMergeSource) read() (mergeEntry, error) {
	var zero mergeEntry
	if m.checked {
		return zero, io.EOF
	}
	for m.remaining == 0 {
		if m.hs != nil {
			// Finish the consumed segment.
			var crcb [crcSize]byte
			if err := readFull(m.r, crcb[:]); err != nil {
				return zero, err
			}
			if binary.LittleEndian.Uint32(crcb[:]) != m.hs.Sum32() {
				return zero, errBadBackup
			}
			m.hf.Write(crcb[:])
			m.segChain = crc32.Update(m.segChain, crc32.IEEETable, crcb[:])
			m.total += uint64(m.remaining)
			m.total = m.total // no-op; cumulative fixed below
			m.hs = nil
			m.seg++
		}
		if m.seg >= m.segCount {
			if err := m.finish(); err != nil {
				return zero, err
			}
			return zero, io.EOF
		}
		if err := m.openNextSegment(); err != nil {
			return zero, err
		}
	}

	ehdr := make([]byte, checkpointEntrySize)
	if err := readFull(m.r, ehdr); err != nil {
		return zero, err
	}
	m.hf.Write(ehdr)
	m.hs.Write(ehdr)
	flag := ehdr[0]
	keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
	valLen := binary.LittleEndian.Uint32(ehdr[5:9])
	seq := binary.LittleEndian.Uint64(ehdr[9:17])
	if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
		keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
		(flag == ckptFlagDelete && valLen != 0) ||
		seq <= m.startWM || seq > m.endWM {
		return zero, errBadBackup
	}
	body := make([]byte, int(keyLen)+int(valLen))
	if err := readFull(m.r, body); err != nil {
		return zero, err
	}
	m.hf.Write(body)
	m.hs.Write(body)
	key := string(body[:keyLen])
	if m.haveKey && key <= m.lastKey {
		return zero, errBadBackup
	}
	m.lastKey, m.haveKey = key, true
	m.remaining--
	return mergeEntry{key: key, flag: flag, value: body[keyLen:], seq: seq}, nil
}

// finish validates the segment tally, footer, terminal file CRC and EOF.
func (m *ringMergeSource) finish() error {
	// Tally entries: total must equal the sum of the segment counts.
	// We did not retain the per-segment counts after openNextSegment advanced;
	// recover by tracking against the footer below, so recompute from the
	// segment headers is unnecessary: the footer total is checked against the
	// streamed count kept in streamedTotal.
	if m.streamedTotal_set {
		_ = m.streamedTotal
	}
	foot := make([]byte, incrFooterSize)
	if err := readFull(m.r, foot); err != nil {
		return err
	}
	m.hf.Write(foot)
	if binary.LittleEndian.Uint64(foot[0:8]) != m.total ||
		binary.LittleEndian.Uint32(foot[8:12]) != m.segCount ||
		binary.LittleEndian.Uint32(foot[12:16]) != m.segChain {
		return errBadBackup
	}
	var terminal [crcSize]byte
	if err := readFull(m.r, terminal[:]); err != nil {
		return err
	}
	if binary.LittleEndian.Uint32(terminal[:]) != m.hf.Sum32() {
		return errBadBackup
	}
	if _, err := m.r.ReadByte(); !errors.Is(err, io.EOF) {
		return errBadBackup
	}
	if m.total > 0 && m.endWM == m.startWM {
		return errBadBackup
	}
	m.checked = true
	return nil
}

