	seen      uint64 // entries streamed across segments
	lastKey   string
	haveKey   bool
}

func newHeadMergeSource(dir string, head manifestInfo) *headMergeSource {
	return &headMergeSource{dir: dir, head: head}
}

func (m *headMergeSource) close() {
	if m.f != nil {
		m.f.Close()
		m.f = nil
	}
}

// openNextSegment opens and validates the header of the next head segment.
func (m *headMergeSource) openNextSegment() error {
	if m.f != nil {
		m.f.Close()
		m.f = nil
	}
