	return nil
}

func (m *headMergeSource) read() (mergeEntry, error) {
	var zero mergeEntry
	for m.remaining == 0 {
		if m.f != nil {
			// Finish the consumed segment: its terminal CRC must verify.
			var crcb [crcSize]byte
			if err := readFull(m.r, crcb[:]); err != nil {
				return zero, err
			}
