		return nil, err
	}
	m := &ringMergeSource{f: f, r: bufio.NewReader(f)}
	hf := crc32.NewIEEE()
	m.hf = hf

	read := func(buf []byte) error {
		if err := readFull(m.r, buf); err != nil {
			return err
		}
		hf.Write(buf)
		return nil
	}

	head := make([]byte, incrRingHeaderSize)
	if err := read(head); err != nil {
		m.close()
		return nil, err
	}
	if binary.LittleEndian.Uint32(head[0:4]) != backupMagic ||
		binary.LittleEndian.Uint32(head[4:8]) != backupVersion {
		m.close()
		return nil, errBadBackup
	}
	m.index = binary.LittleEndian.Uint32(head[8:12])
	prevLink := binary.LittleEndian.Uint32(head[12:16])
	m.startWM = binary.LittleEndian.Uint64(head[16:24])
	m.endWM = binary.LittleEndian.Uint64(head[24:32])
	snaps := binary.LittleEndian.Uint64(head[32:40])
	m.segCount = binary.LittleEndian.Uint32(head[40:44])
