	if binary.LittleEndian.Uint32(shdr[0:4]) != backupMagic ||
		binary.LittleEndian.Uint64(shdr[4:12]) != m.startWM ||
		binary.LittleEndian.Uint64(shdr[12:20]) != m.endWM ||
		binary.LittleEndian.Uint32(shdr[20:24]) != m.index ||
		binary.LittleEndian.Uint32(shdr[24:28]) != m.seg {
		return errBadBackup
	}
	count := binary.LittleEndian.Uint32(shdr[28:32])
	segCum := binary.LittleEndian.Uint64(shdr[32:40])
	if count == 0 || count > maxRecord {
		return errBadBackup
	}
	m.segEntries = count
	m.remaining = count
	// The declared cumulative is checked once the segment's terminal CRC is
	// read and its count finalized.
	m.pendingCum = segCum
	return nil
}

func (m *ringMergeSource) read() (mergeEntry, error) {
	var zero mergeEntry
	if m.checked {
		return zero, io.EOF
	}
	for m.remaining == 0 {
		if m.hs != nil {
			var crcb [crcSize]byte
			if err := readFull(m.r, crcb[:]); err != nil {
				return zero, err
			}
			if binary.LittleEndian.Uint32(crcb[:]) != m.hs.Sum32() {
				return zero, errBadBackup
			}
			m.hf.Write(crcb[:])
