}

// headMergeSource streams the full head. Its segment files are opened lazily
// one at a time, so a head of any segment count costs one open file and one
// bounded read buffer rather than one per segment.
type headMergeSource struct {
	dir  string
	head manifestInfo
	seg  int
	f    *os.File
	r    *bufio.Reader
