}

// openNextSegment opens and validates the header of the next head segment.
func (m *headMergeSource) openNextSegment() error {
	if m.f != nil {
		m.f.Close()
		m.f = nil
	}
	seg := m.head.segments[m.seg]
	f, err := os.Open(filepath.Join(m.dir, segmentName(seg.index)))
