			return zero, err
		}
	}

	ehdr := make([]byte, checkpointEntrySize)
	if err := readFull(m.r, ehdr); err != nil {
		return zero, err
	}
	m.h.Write(ehdr)
	flag := ehdr[0]
	keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
	valLen := binary.LittleEndian.Uint32(ehdr[5:9])
	seq := binary.LittleEndian.Uint64(ehdr[9:17])
	if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
		keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
		(flag == ckptFlagDelete && valLen != 0) ||
		seq == 0 || seq > m.head.watermark {
		return zero, errBadBackup
	}
	body := make([]byte, int(keyLen)+int(valLen))
	if err := readFull(m.r, body); err != nil {
		return zero, err
	}
	m.h.Write(body)
	key := string(body[:keyLen])
	if m.haveKey && key <= m.lastKey {
		return zero, errBadBackup
	}
	m.lastKey, m.haveKey = key, true
	m.remaining--
	m.seen++
	return mergeEntry{key: key, flag: flag, value: body[keyLen:], seq: seq}, nil
}

// ringMergeSource streams one folded ring, validating its header, segments,
// footer and terminal file CRC exactly as scanRing does, one entry at a time.
type ringMergeSource struct {
	f  *os.File
	r  *bufio.Reader
	hf interface {
		Write(p []byte) (int, error)
		Sum32() uint32
	}
	hs interface {
		Write(p []byte) (int, error)
		Sum32() uint32
	}

	index    uint32
	startWM  uint64
	endWM    uint64
	snaps    uint64
	segCount uint32
	seg      uint32

	remaining  uint32 // entries left in the open segment
	segEntries uint32 // count declared by the open segment header
	cumulative uint64 // entries through completed segments
	total      uint64 // cumulative through the open/finished segments
	segChain   uint32
	fileCRC    uint32
	lastKey    string
	haveKey    bool
	checked    bool // footer and terminal CRC already verified
}

func newRingMergeSource(path string, exp ringExpect) (*ringMergeSource, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	m := &ringMergeSource{f: f, r: bufio.NewReader(f)}
	hf := crc32.NewIEEE()
	m.hf = hf

	read := func(buf []byte) error {
		if err := readFull(m.r, buf); err != nil {
			return err
		}
		hf.Write(buf)
		return nil
	}

