	m.remaining--
	return mergeEntry{key: key, flag: flag, value: body[keyLen:], seq: seq}, nil
}

// finish validates the footer, terminal file CRC and clean EOF.
func (m *ringMergeSource) finish() error {
	foot := make([]byte, incrFooterSize)
	if err := readFull(m.r, foot); err != nil {
		return err
	}
	m.hf.Write(foot)
	if binary.LittleEndian.Uint64(foot[0:8]) != m.total ||
		binary.LittleEndian.Uint32(foot[8:12]) != m.segCount ||
		binary.LittleEndian.Uint32(foot[12:16]) != m.segChain {
