package snapshot

import (
	"fmt"
	"path/filepath"
	"testing"
)

func TestScratchMerge(t *testing.T) {
	s := openStore(t, tempDir(t))
	for i := 0; i < 20; i++ {
		if err := s.Put(fmt.Sprintf("k%02d", i), []byte(fmt.Sprintf("v%da", i))); err != nil {
			t.Fatal(err)
		}
	}
	chain := filepath.Join(t.TempDir(), "chain")
	if err := s.Backup(chain); err != nil {
		t.Fatal(err)
	}
	for r := 1; r <= 4; r++ {
		// touch a rotating subset, including deletes
		for i := 0; i < 20; i++ {
			if i%4 == r%4 {
				if err := s.Delete(fmt.Sprintf("k%02d", i)); err != nil {
					t.Fatal(err)
				}
			} else if i%3 == r%3 {
				if err := s.Put(fmt.Sprintf("k%02d", i), []byte(fmt.Sprintf("v%dr%d", i, r))); err != nil {
					t.Fatal(err)
				}
			}
		}
		if _, err := s.Snapshot(); err != nil {
			t.Fatal(err)
		}
		if err := s.BackupIncremental(chain); err != nil {
			t.Fatal(err)
		}
	}
	wantTip := allPairs(t, s)
	t.Logf("tip pairs=%d", len(wantTip))

	// fold 2 of 4
	if err := s.MergeChain(chain, 2); err != nil {
		t.Fatal(err)
	}
	// ring files present: 1,2 only
	for _, n := range []uint32{1, 2} {
		if _, err := readRingFileForTest(t, chain, n); err != nil {
			t.Fatalf("ring %d: %v", n, err)
		}
	}
	rs, target := restoreCheckpoint(t, chain, wantTip, s.Stats().Snapshots)
	rs.Close()
	t.Logf("restored to %s; pairs match", target)

	// append a fresh ring after merge and restore again
	if err := s.Put("brandnew", []byte("z")); err != nil {
		t.Fatal(err)
	}
	if err := s.BackupIncremental(chain); err != nil {
		t.Fatal(err)
	}
	rs2, _ := restoreCheckpoint(t, chain, allPairs(t, s), s.Stats().Snapshots)
	rs2.Close()
}

func readRingFileForTest(t *testing.T, dir string, idx uint32) (int64, error) {
	t.Helper()
	// parse just the header via load path is not exported; stat instead
	return ringStatForTest(dir, idx)
}

