	}
	after, err := os.ReadDir(chain)
	if err != nil {
		t.Fatal(err)
	}
	if len(after) != len(before)+1 {
		t.Fatalf("entries=%d want %d", len(after), len(before)+1)
	}
	if _, err := os.Stat(obs); !os.IsNotExist(err) {
		t.Fatal("obs debris left behind")
	}

	// Simulate a kill after the new chain landed: obs parked beside new chain.
	st := mergeStagePath(chain)
	if err := os.MkdirAll(st, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(st, "x"), []byte("junk"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(obs, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := s.MergeChain(chain, 1); err != nil {
		t.Fatalf("merge clearing debris: %v", err)
	}
	if _, err := os.Stat(obs); !os.IsNotExist(err) {
		t.Fatal("obs not removed after completed merge")
	}
	if _, err := os.Stat(st); !os.IsNotExist(err) {
		t.Fatal("stage not removed after completed merge")
	}
}

