func Open(dir string) (*Store, error) {
	info, err := os.Stat(dir)
	if err == nil {
		if !info.IsDir() {
			return nil, errNotDir
		}
	} else {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		}
		if err := os.MkdirAll(dir, 0o700); err != nil {
			return nil, err
		}
	}

	// A replacement log from a compaction killed before its rename can never
	// be complete state of record; the old wal.log is. Drop the stale file.
	// Likewise, staging debris from a kill mid-checkpoint (a half-built layer
	// temp or a legacy single-file temp) is swept: only finished layers are
	// ever read.
	if err := removeStaleCompact(dir); err != nil {
		return nil, err
	}
	if err := sweepCheckpointDebris(dir); err != nil {
		return nil, err
	}
	if err := sweepStagedChain(dir); err != nil {
		return nil, err
	}
	// Sweep debris from a hot backup that was killed before its manifest, and
	// from a restore killed before its target rename. These names never appear
	// in a live store, so a store that was merely backed up is unaffected.
	if err := openBackupSweep(dir); err != nil {
		return nil, err
	}
	// Heal or clear debris of a chain merge killed around its directory swap.
	// The debris is a sibling of dir named after dir, so opening an unrelated
	// store never touches another directory's merge.
	if err := sweepMergeLeftovers(dir); err != nil {
		return nil, err
	}
	sweepRestoreDebris(dir)

	latest := newView(nil)
	var replaySeq uint64

