func TestMergeChainOpenHealsParkedChain(t *testing.T) {
	s := openStore(t, tempDir(t))
	chain := buildMultiRingChain(t, s, 1)
	want := dirFileHashes(t, chain)

	// Kill between the two swap renames: the chain name is gone, parked aside.
	obs := mergeObsPath(chain)
	if err := os.Rename(chain, obs); err != nil {
		t.Fatal(err)
	}
	storeDir := t.TempDir()
	missing := filepath.Join(storeDir, "chain")

	// Opening the missing name heals the parked chain back into place instead
	// of creating an empty directory over it.
	st, err := Open(missing)
	if err != nil {
		t.Fatalf("open heals parked chain: %v", err)
	}
	st.Close()
	got := dirFileHashes(t, missing)
	if len(got) != len(want) {
		t.Fatalf("healed chain has %d files, want %d", len(got), len(want))
	}
	for name, h := range want {
		if got[name] != h {
			t.Fatalf("healed file %q differs from parked chain", name)
		}
	}
	if _, err := os.Stat(obs); !errors.Is(err, fs.ErrNotExist) {
		t.Fatal("parked copy left after open heal")
	}
	// The healed chain still restores.
	rs, err := Restore(missing, filepath.Join(t.TempDir(), "r"))
	if err != nil {
		t.Fatalf("restore healed chain: %v", err)
	}
	rs.Close()
}

